def roman_to_int(s):
    if not s:
        return 0
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for ch in reversed(s):
        v = values.get(ch, 0)
        if v < prev:
            total -= v
        else:
            total += v
        prev = max(prev, v)
    return total
```

