def two_sum(xs, target):
    n = len(xs)
    if n < 2:
        return None
    positions = {}
    for idx, x in enumerate(xs):
        positions.setdefault(x, []).append(idx)
    for i in range(n):
        comp = target - xs[i]
        for j in positions.get(comp, ()):
            if j > i:
                return (i, j)
    return None
```

