def parse_query(qs):
    if qs is None:
        return {}
    qs = qs.strip()
    if not qs:
        return {}
    if qs.startswith('?'):
        qs = qs[1:]
    result = {}
    for pair in qs.split('&'):
        if not pair:
            continue
        if '=' in pair:
            key, _, value = pair.partition('=')
        else:
            key, value = pair, ''
        if key in result:
            if not isinstance(result[key], list):
                result[key] = [result[key]]
            result[key].append(value)
        else:
            result[key] = value
    return result
```

