def word_wrap(text, width):
    if width <= 0:
        raise ValueError("width must be positive")
    if text is None or not text.strip():
        return []
    words = text.split()
    lines = []
    current = ""
    for word in words:
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word
        while len(current) > width and " " in current:
            # place overly long current line if possible (shouldn't normally happen)
            lines.append(current)
            current = ""
    if current:
        lines.append(current)
    return lines
```

